<?php
/** @noinspection PhpUnhandledExceptionInspection */
declare(strict_types=1);

// Test generated by Claude Code.

namespace Tests\Store\Action\Query;

use Module\Store\Action\Dto\StoreShortDto;
use Module\Store\Action\Query\GetStoreByExternalIdQry;
use Module\Store\Model\Store;
use Module\Store\Model\StoreRepository;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\Attributes\Test;
use Tests\IntegrationTestCase;

class GetStoreByExternalIdQryTest extends IntegrationTestCase
{
    private GetStoreByExternalIdQry $sut;

    private StoreRepository $storeRepository;

    public function setUp(): void
    {
        parent::setUp();

        $this->storeRepository = $this->container->get(StoreRepository::class);

        $this->sut = new GetStoreByExternalIdQry($this->storeRepository);
        $this->prepareDb();
    }

    #[Test, DataProvider('dataProviderHandle')]
    public function handle(string $extId, ?StoreShortDto $expected): void
    {
        $result = $this->sut->handle($extId);

        $this->assertEquals($expected, $result);
    }

    /**
     * @return array<string, array<string, mixed>>
     */
    public static function dataProviderHandle(): array
    {
        return [
            'found' => [
                'extId' => 'EXT-10',
                'expected' => new StoreShortDto(10, 'EXT-10', 'Test Store'),
            ],
            'not found returns null' => [
                'extId' => 'EXT-UNKNOWN',
                'expected' => null,
            ],
        ];
    }

    private function prepareDb(): void
    {
        $this->storeRepository->saveWithId(Store::factory('EXT-10', 'Test Store', '1 Main St', 10));
        $this->storeRepository->flush();
    }
}
